EMBEDDED_PAYLOAD_ZIP_SHA256 = "7dfd4a56b03db31a055e804e6641247a4ccf2aa00d25a69b256d6c2acd17345f"
EMBEDDED_PAYLOAD_MANIFEST_SHA256 = "a07d6086096307939ed40c50112cd1d47eb2dd09ea9fadaac0f45f5891611262"
RESUME_MATRIX_NAME = Path("resume/runtime_recipe_bakeoff.csv")


def main() -> int:
    """Upgrade torch, extract the payload, and run or import-check the bake-off.

    Returns:
        Process exit status.

    """
    output_dir = _output_dir()
    _require_python_version()
    _ensure_latest_torch()
    payload_dir = _extract_payload(_payload_extract_dir(output_dir))
    payload_src = payload_dir / "src"
    if os.environ.get(IMPORT_ONLY_ENV) == "1":
        _write_import_proof(payload_src=payload_src, output_dir=output_dir)
        return 0
    require_resume = _seed_resume_matrix(
        payload_dir=payload_dir,
        output_dir=output_dir,
    )
    _run_bakeoff(
        payload_src=payload_src,
        output_dir=output_dir,
        require_resume=require_resume,
    )
    _verify_bakeoff(payload_src=payload_src, output_dir=output_dir)
    _assert_kaggle_output(output_dir)
    return 0


def _run_bakeoff(
    *,
    payload_src: Path,
    output_dir: Path,
    require_resume: bool,
) -> None:
    command = [
        sys.executable,
        "-m",
        BAKEOFF_MODULE,
        "--output-dir",
        str(output_dir),
    ]
    if require_resume:
        command.append("--require-resume")
    subprocess.run(  # noqa: S603
        tuple(command),
        check=True,
        cwd=output_dir,
        env=_payload_environment(payload_src),
    )


def _verify_bakeoff(*, payload_src: Path, output_dir: Path) -> None:
    subprocess.run(  # noqa: S603
        (
            sys.executable,
            "-m",
            BAKEOFF_MODULE,
            "--output-dir",
            str(output_dir),
            "--verify-output",
        ),
        check=True,
        cwd=output_dir,
        env=_payload_environment(payload_src),
    )


def _write_import_proof(*, payload_src: Path, output_dir: Path) -> None:
    environment = _payload_environment(payload_src)
    subprocess.run(  # noqa: S603
        (
            sys.executable,
            "-c",
            (
                "import importlib, json, pathlib; "
                f"m=importlib.import_module({BAKEOFF_MODULE!r}); "
                "p=pathlib.Path('benchmark'); p.mkdir(exist_ok=True); "
                "(p/'runtime_recipe_bakeoff_import.json').write_text("
                "json.dumps({'status':'import_pass','schema_version':m.SCHEMA_VERSION})"
                "+'\\n', encoding='utf-8')"
            ),
        ),
        check=True,
        cwd=output_dir,
        env=environment,
    )


def _payload_environment(payload_src: Path) -> dict[str, str]:
    environment = os.environ.copy()
    environment.pop("EQVAE_DATA_ROOT", None)
    paths = [str(payload_src)]
    if environment.get("PYTHONPATH"):
        paths.append(environment["PYTHONPATH"])
    environment["PYTHONPATH"] = os.pathsep.join(paths)
    environment["OMP_NUM_THREADS"] = "1"
    environment["MKL_NUM_THREADS"] = "1"
    return environment


def _output_dir() -> Path:
    configured = os.environ.get("EQVAE_OUTPUT_DIR")
    output_dir = Path(configured) if configured else DEFAULT_OUTPUT_DIR
    output_dir.mkdir(parents=True, exist_ok=True)
    return output_dir.resolve()


def _payload_extract_dir(output_dir: Path) -> Path:
    if Path("/kaggle/temp").exists():
        return Path("/kaggle/temp/eqvae_runtime_recipe_bakeoff_payload")
    if Path("/tmp").exists():  # noqa: S108
        return Path("/tmp/eqvae_runtime_recipe_bakeoff_payload")  # noqa: S108
    return output_dir / "embedded_payload"


def _require_python_version() -> None:
    if sys.version_info < (3, 12):  # noqa: UP036
        message = "runtime-recipe bake-off requires Python >= 3.12"
        raise RuntimeError(message)


def _ensure_latest_torch() -> None:
    """Upgrade torch and its bundled CUDA runtime before importing the payload.

    Raises:
        RuntimeError: If a Kaggle process attempts to bypass the mandatory upgrade.

    """
    if not Path("/kaggle/working").exists():
        return
    if os.environ.get("EQVAE_SKIP_TORCH_UPGRADE") == "1":
        message = "EQVAE_SKIP_TORCH_UPGRADE is forbidden on Kaggle"
        raise RuntimeError(message)
    subprocess.run(
        (
            sys.executable,
            "-m",
            "pip",
            "install",
            "--upgrade",
            "--no-cache-dir",
            "torch",
            "torchvision",
            "torchaudio",
        ),
        check=True,
    )


def _extract_payload(destination: Path) -> Path:
    if destination.exists():
        shutil.rmtree(destination)
    destination.mkdir(parents=True)
    zip_bytes = base64.b64decode(EMBEDDED_PAYLOAD_B64.encode("ascii"))
    if hashlib.sha256(zip_bytes).hexdigest() != EMBEDDED_PAYLOAD_ZIP_SHA256:
        message = "embedded payload zip SHA-256 mismatch"
        raise RuntimeError(message)
    with zipfile.ZipFile(io.BytesIO(zip_bytes)) as archive:
        for member in archive.infolist():
            member_path = Path(member.filename)
            if member_path.is_absolute() or ".." in member_path.parts:
                message = f"unsafe embedded payload path: {member.filename}"
                raise RuntimeError(message)
        archive.extractall(destination)
    manifest = destination / "payload_manifest.json"
    if hashlib.sha256(manifest.read_bytes()).hexdigest() != (
        EMBEDDED_PAYLOAD_MANIFEST_SHA256
    ):
        message = "embedded payload manifest SHA-256 mismatch"
        raise RuntimeError(message)
    return destination


def _seed_resume_matrix(*, payload_dir: Path, output_dir: Path) -> bool:
    """Atomically seed the prior evidence matrix when this payload carries one.

    Returns:
        Whether a resume matrix was present and seeded.

    Raises:
        TypeError: If the embedded payload manifest is not an object.
        RuntimeError: If the resume matrix does not match its embedded digest.

    """
    source = payload_dir / RESUME_MATRIX_NAME
    if not source.is_file():
        return False
    manifest = json.loads(
        (payload_dir / "payload_manifest.json").read_text("utf-8"),
    )
    if not isinstance(manifest, dict):
        message = "embedded payload manifest must be an object"
        raise TypeError(message)
    entries = manifest.get("entries")
    expected = (
        entries.get(RESUME_MATRIX_NAME.as_posix())
        if isinstance(entries, dict)
        else None
    )
    actual = hashlib.sha256(source.read_bytes()).hexdigest()
    if not isinstance(expected, str) or actual != expected:
        message = "embedded resume matrix SHA-256 mismatch"
        raise RuntimeError(message)
    destination = output_dir / "benchmark" / RESUME_MATRIX_NAME.name
    destination.parent.mkdir(parents=True, exist_ok=True)
    temporary = destination.with_suffix(f"{destination.suffix}.tmp")
    shutil.copyfile(source, temporary)
    temporary.replace(destination)
    return True


def _assert_kaggle_output(output_dir: Path) -> None:
    root = Path("/kaggle/working").resolve()
    resolved = output_dir.resolve()
    if resolved != root and root not in resolved.parents:
        message = f"bake-off output must be under {root}, got {resolved}"
        raise RuntimeError(message)


if __name__ == "__main__":
    raise SystemExit(main())
